"""Generated by Mini-Maestro from a validated workflow payload."""
from datetime import datetime

from airflow import DAG
from airflow.operators.python import PythonOperator
from airflow.providers.smtp.operators.smtp import EmailOperator
from airflow.providers.standard.sensors.filesystem import FileSensor


def read_data(**context):
    import json
    with open('/opt/airflow/input/data.json', encoding='utf-8') as file:
        data = json.load(file)
    context['ti'].xcom_push(key='raw_data', value=data)
    print(f'Read {len(data)} records')


def process_data(**context):
    raw_data = context['ti'].xcom_pull(task_ids='read_data', key='raw_data')
    qualified = [employee for employee in raw_data if employee.get('score', 0) >= 80]
    processed_data = {
        'qualified_employees': qualified,
        'total_qualified': len(qualified),
        'average_score': sum(employee['score'] for employee in qualified) / len(qualified) if qualified else 0
    }
    context['ti'].xcom_push(key='processed_data', value=processed_data)
    print(processed_data)


def save_result(**context):
    import json
    processed_data = context['ti'].xcom_pull(task_ids='process_data', key='processed_data')
    with open('/opt/airflow/output/result.json', 'w', encoding='utf-8') as file:
        json.dump(processed_data, file, indent=2)
    print('Result saved successfully')


with DAG(
    dag_id="dynamic_employee_test",
    start_date=datetime(2026, 1, 1),
    schedule=None,
    catchup=False,
    tags=["mini-maestro", "generated"],
) as dag:


    file_sensor = FileSensor(
        task_id="file_sensor",
        filepath="/opt/airflow/input/data.json",
        poke_interval=5,
        timeout=60,
        mode="reschedule",
    )



    read_data = PythonOperator(
        task_id="read_data",
        python_callable=read_data,
    )



    process_data = PythonOperator(
        task_id="process_data",
        python_callable=process_data,
    )



    save_result = PythonOperator(
        task_id="save_result",
        python_callable=save_result,
    )



    file_sensor >> read_data

    read_data >> process_data

    process_data >> save_result
